{
  "title": "Snacks, Surprises and a Splurge",
  "summary": "A slow, food-loving Sunday around Ubud with a market-style lunch, a hidden temple, a proper splurge dinner and an unexpected nightcap.",
  "stops": [
    {
      "poi_id": "p7",
      "kind": "activity",
      "must_do_id": null,
      "note": "A gentle ridge walk to wake up late and earn the first bite. The sun won’t wait."
    },
    {
      "poi_id": "p16",
      "kind": "meal",
      "must_do_id": null,
      "note": "Lunch with a market-like spread of colourful vegan plates. Terima kasih (thank you), Ubud."
    },
    {
      "poi_id": "p10",
      "kind": "activity",
      "must_do_id": null,
      "note": "A cave temple stop nobody saw coming. I know a guy who swears by the carvings."
    },
    {
      "poi_id": "p20",
      "kind": "meal",
      "must_do_id": "m2",
      "note": "The splurge stays put, slow and celebratory. Rise and shine for the tasting menu."
    },
    {
      "poi_id": "p13",
      "kind": "activity",
      "must_do_id": null,
      "note": "A beach-club nightcap far from Ubud’s calm, because this crew is all night owls."
    }
  ]
}

{
